import{_ as e,c as t,o as a,a4 as r}from"./chunks/framework.Cn-pVit8.js";const g=JSON.parse('{"title":"Gitlab API","description":"","frontmatter":{},"headers":[],"relativePath":"前端工程化/CI-CD.md","filePath":"前端工程化/CI-CD.md","lastUpdated":1713170519000}'),o={name:"前端工程化/CI-CD.md"},c=r('<h1 id="gitlab-api" tabindex="-1"><a href="https://docs.gitlab.com/ee/api/rest/" target="_blank" rel="noreferrer">Gitlab API</a> <a class="header-anchor" href="#gitlab-api" aria-label="Permalink to &quot;[Gitlab API](https://docs.gitlab.com/ee/api/rest/)&quot;">​</a></h1><p>使用 Gitlab api 查询仓库信息 API 参考: <a href="https://docs.gitlab.com/ee/api/repositories.html" target="_blank" rel="noreferrer">https://docs.gitlab.com/ee/api/repositories.html</a> 获取参考文件目录: <a href="https://gitlab.com/api/v4/projects/%7BprojectId%7D/repository/tree?recursive=true&amp;ref=%E5%88%86%E6%94%AF%E5%90%8D" target="_blank" rel="noreferrer">https://gitlab.com/api/v4/projects/{projectId}/repository/tree?recursive=true&amp;ref=分支名</a></p><p>gitlab api url 中的 query 必须与文档上的一致，不能随意使用 encodeURIComponent</p><h1 id="gitlab-ci-cd" tabindex="-1"><a href="https://docs.gitlab.cn/jh/ci/quick_start/" target="_blank" rel="noreferrer">GitLab CI/CD</a> <a class="header-anchor" href="#gitlab-ci-cd" aria-label="Permalink to &quot;[GitLab CI/CD](https://docs.gitlab.cn/jh/ci/quick_start/)&quot;">​</a></h1><p><a href="https://cloud.tencent.com/developer/tools/blog-entry?target=http%3A%2F%2Fmp.weixin.qq.com%2Fs%3F__biz%3DMzI3ODcxMzQzMw%3D%3D%26mid%3D2247492810%26idx%3D2%26sn%3Dc6b25b7106baf4d0e1a31f3b5fdd79f5%26chksm%3Deb5061fcdc27e8ea6dee6534b0bc255fee020fcacda3a44dfac7d24a2b825615c3d44653da4d%26scene%3D21%23wechat_redirect&amp;source=article&amp;objectId=1684099" target="_blank" rel="noreferrer">GitLab</a> CI/CD 由一个名为 .gitlab-ci.yml 的文件进行配置，改文件位于仓库的根目录下。文件中指定的脚本由GitLab Runner执行。</p><p>一个简单的管道通常包括三个阶段：build、test、deploy</p><h1 id="github-action" tabindex="-1"><a href="https://docs.github.com/en/actions/quickstart" target="_blank" rel="noreferrer">Github Action</a> <a class="header-anchor" href="#github-action" aria-label="Permalink to &quot;[Github Action](https://docs.github.com/en/actions/quickstart)&quot;">​</a></h1><p>某个【event】发生时，执行某些动作【action】。</p><p><code>.github/workflows/xxx.yaml</code>，<code>.github/workflows</code> 目录下的一个 YAML 文件就是一个 workflow。</p><p><strong>workflow</strong>：workflow 包含一个或多个 <strong>jobs</strong> ，jobs 之间可以顺序执行也可以并行执行，每个 job 在自己的虚拟机上或容器中运行，每个 job 包含一个或多个 step，每个 step 运行自定义脚本或 action。</p><p>同一个 job 中的 <code>step</code> 在同一个 <code>runner</code> 中执行，因此这些 <code>step</code> 可以共享数据和文件。</p><p><a href="https://www.ruanyifeng.com/blog/2019/09/getting-started-with-github-actions.html" target="_blank" rel="noreferrer">GitHub Actions 入门教程-阮一峰</a></p><h1 id="docker" tabindex="-1">docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;docker&quot;">​</a></h1><p><a href="https://juejin.cn/post/7178673705462169655" target="_blank" rel="noreferrer">docker 部署并运行 Node项目</a></p>',14),i=[c];function s(n,l,p,d,b,h){return a(),t("div",null,i)}const u=e(o,[["render",s]]);export{g as __pageData,u as default};
